import{_ as n,C as i,c as r,o as a,a3 as s,G as o}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Close a session","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/sessions/close-session.md","filePath":"master/sales/point-of-sale/sessions/close-session.md","lastUpdated":1791902625000}'),l={name:"master/sales/point-of-sale/sessions/close-session.md"};function c(h,e,g,d,u,m){const t=i("ImagePopup");return a(),r("div",null,[e[0]||(e[0]=s('<h1 id="close-a-session" tabindex="-1">Close a session <a class="header-anchor" href="#close-a-session" aria-label="Permalink to &quot;Close a session&quot;">​</a></h1><p>Closing a session ends the working period of a register. You count the cash in the drawer, compare it with what the system expects, and post the day&#39;s sales to accounting. Do it at the end of every shift or day so your books stay current.</p><blockquote><p><strong>In simple words:</strong> Count the drawer, tell the system the amount, and click Confirm. Aureus does the accounting for you.</p></blockquote><h2 id="before-you-close" tabindex="-1">Before you close <a class="header-anchor" href="#before-you-close" aria-label="Permalink to &quot;Before you close&quot;">​</a></h2><ul><li>Finish or cancel every order that is still <strong>New</strong>. A session with unfinished orders cannot close. The terminal shows the message &quot;You cannot close the POS when orders are still in draft&quot; with <strong>Review Orders</strong> and <strong>Cancel Orders</strong>.</li><li>Record any cash in and out. See <a href="./cash-in-and-out.html">Cash in and out</a>.</li><li>Count the cash in the drawer.</li></ul><h2 id="close-from-the-back-office" tabindex="-1">Close from the back office <a class="header-anchor" href="#close-from-the-back-office" aria-label="Permalink to &quot;Close from the back office&quot;">​</a></h2><ol><li>Go to <code>Point of Sale → Orders → Sessions</code>.</li><li>Find the session that is <strong>In Progress</strong>.</li><li>Click <strong>Close Session</strong> on its row.</li></ol>',7)),o(t,{src:"/images1/pos/sessions_row_actions.png",alt:"Sessions list with the Close Session action on the In Progress session"}),e[1]||(e[1]=s('<ol start="4"><li>In the <strong>Close Session</strong> window, fill in the form.</li></ol><ul><li><strong><em>Counted Cash:</em></strong> The cash you counted in the drawer. The hint shows the <strong>Expected balance</strong>, so you can compare. If you leave it empty, Aureus uses the expected balance.</li><li><strong><em>Notes:</em></strong> An optional remark, such as &quot;Drawer counted at closing, matches the expected balance&quot;.</li><li><strong><em>Balancing Account:</em></strong> An account used only when the closing entry does not balance. Leave it empty if you do not need it.</li></ul><ol start="5"><li>Click <strong>Confirm</strong>. A notice says <strong>Session closed</strong>.</li></ol>',3)),o(t,{src:"/images1/pos/close_session_window.png",alt:"Close Session window with Counted Cash 7847, Expected balance 7847, a note and the Confirm button"}),e[2]||(e[2]=s('<p><strong>Example:</strong> TechNest expects 7,847 (1,750 opening, plus 6,597 cash sales, minus the 500 courier payment, with the refund netting out). The cashier counts 7,847 and enters it. The difference is zero.</p><h2 id="close-from-the-terminal" tabindex="-1">Close from the terminal <a class="header-anchor" href="#close-from-the-terminal" aria-label="Permalink to &quot;Close from the terminal&quot;">​</a></h2><p>The cashier can close without leaving the till.</p><ol><li>Click your initials at the top right of the terminal.</li><li>Click <strong>Close register</strong>. The <strong>Closing register</strong> screen opens.</li><li>Read the summary: <strong>Opening</strong>, <strong>Payments in cash</strong>, <strong>Cash in / Out</strong> and <strong>Expected in drawer</strong>.</li><li>Enter the <strong>Counted</strong> amount. Use <strong>Cash count</strong> to count by coin and note, or the copy icon to copy the expected amount.</li><li>Add a <strong>Closing note</strong> if you wish. The <strong>Difference</strong> shows what is missing or extra.</li><li>Click <strong>Close register</strong>.</li></ol>',4)),o(t,{src:"/images1/pos/terminal_closing_register.png",alt:"Terminal Closing register screen with expected amount, counted amount, difference and the Close register button"}),e[3]||(e[3]=s('<p>If a payment method other than cash is used, the screen also lists it with its own <strong>Counted</strong> and <strong>Difference</strong>. Click <strong>Back to the till</strong> to leave without closing.</p><h2 id="difference-limits" tabindex="-1">Difference limits <a class="header-anchor" href="#difference-limits" aria-label="Permalink to &quot;Difference limits&quot;">​</a></h2><p>A register can set a <strong>Maximum Difference</strong>. If the counted cash is further from the expected cash than that limit, only a manager can close. The terminal says &quot;The difference is above the allowed limit. Only a manager can close this register.&quot; Set the limit in the <strong>Payment</strong> tab of the register. See <a href="./../get-started/set-up-a-register.html">Set up a register</a>.</p><h2 id="what-closing-does" tabindex="-1">What closing does <a class="header-anchor" href="#what-closing-does" aria-label="Permalink to &quot;What closing does&quot;">​</a></h2><p>When you confirm, Aureus does these things in one step.</p><ol><li>Saves the <strong>Ending Balance</strong> (what the system expected), the counted cash and the <strong>Cash Difference</strong>.</li><li>Posts one closing journal entry in the register&#39;s journal. It records the sales, the taxes and the money received by each payment method. Orders that were invoiced are settled through the customer invoice instead.</li><li>Posts a second entry for the cost of goods sold, if <strong>Post Cost of Goods Sold</strong> is on in the register&#39;s <strong>Accounting</strong> tab. It uses the <strong>Stock Output Account</strong>.</li><li>Updates stock. Your inventory setting decides the timing: <strong>In real time</strong> moves stock as you sell. <strong>At the session closing</strong> moves it now.</li><li>Changes every paid order to <strong>Posted</strong> and the session to <strong>Closed &amp; Posted</strong>.</li></ol><p>If the entry does not balance, Aureus needs a <strong>Balancing Account</strong>. The default is set in the register&#39;s <strong>Accounting</strong> tab and in <code>Point of Sale → Settings</code>. Without one, the close stops with a message that shows the amount. See <a href="./../get-started/pos-settings.html">POS settings</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Choose <strong>Closed</strong> in the Sessions list to review old sessions. The <strong>View</strong> action shows their orders and payments.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>You cannot reopen a closed session. Check the counted cash before you click <strong>Confirm</strong>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Register sessions</a></li><li><a href="./../reporting/session-report.html">Session report</a></li><li><a href="./../../../finance/customer-invoices/">Customer invoices</a></li></ul>',11))])}const _=n(l,[["render",c]]);export{p as __pageData,_ as default};
